import { describe, expect, it } from "vitest";
import { ConfigError, parseConfig, parseThreshold, parseYamlSubset } from "../src/config.js";

describe("parseConfig", () => {
  it("parses the documented shape", () => {
    const text =
      "# pharn-ci\ncoverage:\n  file: coverage/lcov.info # generated by vitest\n  format: lcov\n  threshold: 80\n";
    expect(parseConfig(text)).toEqual({ coverage: { file: "coverage/lcov.info", format: "lcov", threshold: 80 } });
  });

  it("accepts an empty file and an empty section", () => {
    expect(parseConfig("")).toEqual({});
    expect(parseConfig("coverage:\n")).toEqual({});
  });

  it("accepts quoted strings, decimals and null fields", () => {
    const text = '---\ncoverage:\n  file: "cov/lcov #1.info"\n  threshold: 72.5\n  format: ~\n';
    expect(parseConfig(text)).toEqual({ coverage: { file: "cov/lcov #1.info", threshold: 72.5 } });
  });

  it.each([
    ["coverage:\n  treshold: 80\n", 'unknown key "coverage.treshold"'],
    ["covrage:\n  file: x\n", 'unknown top-level key "covrage"'],
    ["coverage:\n  threshold: 101\n", "between 0 and 100"],
    ["coverage:\n  threshold: high\n", "between 0 and 100"],
    ["coverage:\n  format: jacoco\n", "must be one of: lcov, cobertura"],
    ["coverage: lcov\n", "must be a mapping"],
    ["coverage:\n  - file: x\n", "lists are not supported"],
    ["coverage: { file: x }\n", "unsupported YAML syntax"],
    ["coverage:\n  file: a\n  file: b\n", 'duplicate key "file"'],
    ["coverage:\n  file: a\n    nested: b\n", "unexpected indentation"],
    ["coverage:\n\tfile: a\n", "tabs are not allowed"],
    ["just text\n", 'expected "key: value"'],
  ])("rejects %j", (text, message) => {
    expect(() => parseConfig(text)).toThrow(ConfigError);
    expect(() => parseConfig(text)).toThrow(message);
  });
});

describe("parseYamlSubset", () => {
  it("parses nesting, booleans and single-quoted strings", () => {
    expect(parseYamlSubset("a:\n  b:\n    c: true\n  d: 'it''s'\ne: false\n")).toEqual({
      a: { b: { c: true }, d: "it's" },
      e: false,
    });
  });
});

describe("parseThreshold", () => {
  it("accepts numbers and numeric strings in range", () => {
    expect(parseThreshold("0")).toBe(0);
    expect(parseThreshold(" 80 ")).toBe(80);
    expect(parseThreshold(100)).toBe(100);
  });

  it.each(["", "abc", "-1", "100.1", Number.NaN])("rejects %j", (value) => {
    expect(() => parseThreshold(value)).toThrow(ConfigError);
  });
});
